import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`law-firm-marketing-audit`,hasInputUrl:!0,heroTitle:`See why your law firm isn't getting found.`,heroSubtitle:`Perplexity Computer audits your website, checks your local rankings, and builds your growth plan — automatically.`,heroCta:`Audit My Firm`,inputUrlCta:`Audit My Firm`,inputUrlPlaceholder:`Your firm's website`,inputUrlPrefill:`Run a marketing audit for this law firm: {url}. 1) Audit the website for conversion gaps, missing practice-area pages, and weak calls to action. 2) Check local SEO: Google Business Profile, reviews, and map-pack visibility. 3) Compare against two local competitors. 4) Identify the highest-intent keywords for the firm's practice areas. 5) Build a 90-day growth plan ranked by impact.`,heroOverlaySteps:[`Find the conversion gaps and missing pages costing you cases`,`Check your Google Business Profile, reviews, and map-pack visibility`,`Show where local rivals outrank you and why`,`A website audit — ready to use`],generatingSteps:[`Visiting {url} to get started`,`Designing an agent for your task`,`Configuring the analysis`,`Setting up your deliverable`],featureSectionTitle:`From an invisible firm to a full pipeline`,featureCardTitles:[`Connects to your marketing stack`,`Outputs that bring in cases`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Search Console, Google Analytics, Ahrefs, Google Sheets — Computer audits visibility and builds the plan in the tools you already use.`,`A website audit. A local SEO report. A competitor comparison. A 90-day growth plan.`],capabilitySectionTitle:`Your marketing analyst, on autopilot`,capabilitySectionSubtitle:`Paste your firm's URL, step away, and come back to an audit and a growth plan.`,capabilityCards:[{title:`Website Audit`,description:`Computer can find the conversion gaps and missing pages costing you cases.`},{title:`Local SEO Check`,description:`Computer can check your Google Business Profile, reviews, and map-pack visibility.`},{title:`Competitor Compare`,description:`Computer can show where local rivals outrank you and why.`},{title:`Connect Your Tools`,description:`Computer can pull data from Search Console, Analytics, and Ahrefs into Sheets.`},{title:`Remembers Your Firm`,description:`Computer can remember your practice areas and track progress over time.`},{title:`Monitor & Alert`,description:`Computer can watch your rankings and flag a competitor's new move.`}]});export{t as default};
